/* ChartPulse — Design System */
:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #1a1a2e;
  --bg-card: #16213e;
  --bg-surface: #1e1e32;
  --bg-hover: #252542;
  --border-color: #2a2a3e;
  --border-light: #353550;
  --text-primary: #f0f0f0;
  --text-secondary: #999;
  --text-muted: #666;
  --accent: #2962FF;
  --accent-hover: #1e4fdb;
  --accent-dim: rgba(41, 98, 255, 0.15);
  --positive: #00C853;
  --positive-dim: rgba(0, 200, 83, 0.12);
  --negative: #F7525F;
  --negative-dim: rgba(247, 82, 95, 0.12);
  --warning: #FFA726;
  --gold: #FFD700;
  --platinum: #E5E4E2;
  --radius: 6px;
  --radius-lg: 10px;
  --radius-sm: 4px;
  --font: 'Inter', 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', monospace;
  --shadow: 0 2px 8px rgba(0,0,0,0.3);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.5);
  --transition: 150ms ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }
body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

a { color: var(--accent); text-decoration: none; }
a:hover { color: #5c85ff; }
ul { list-style: none; }

/* Header / Nav */
.navbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  height: 56px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 100;
  gap: 16px;
}
.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 20px;
  font-weight: 700;
  color: #fff;
  white-space: nowrap;
}
.nav-logo .icon { font-size: 24px; }
.nav-links {
  display: flex;
  gap: 4px;
}
.nav-links a {
  padding: 8px 16px;
  border-radius: var(--radius);
  color: var(--text-secondary);
  font-size: 14px;
  font-weight: 500;
  transition: all var(--transition);
}
.nav-links a:hover, .nav-links a.active { color: #fff; background: var(--bg-hover); }
.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}
.nav-actions .btn { font-size: 13px; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 20px;
  border-radius: var(--radius);
  font-weight: 600;
  font-size: 14px;
  cursor: pointer;
  border: none;
  transition: all var(--transition);
  font-family: var(--font);
  white-space: nowrap;
}
.btn-primary { background: var(--accent); color: #fff; }
.btn-primary:hover { background: var(--accent-hover); }
.btn-outline {
  background: transparent;
  border: 1px solid var(--border-light);
  color: var(--text-primary);
}
.btn-outline:hover { background: var(--bg-hover); border-color: #555; }
.btn-sm { padding: 6px 12px; font-size: 12px; }
.btn-xs { padding: 3px 8px; font-size: 11px; border-radius: var(--radius-sm); }

/* Tabs */
.tabs {
  display: flex;
  gap: 2px;
  background: var(--bg-surface);
  border-radius: var(--radius);
  padding: 3px;
}
.tab {
  padding: 7px 14px;
  border-radius: var(--radius-sm);
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  border: none;
  background: transparent;
  font-family: var(--font);
  transition: all var(--transition);
  white-space: nowrap;
}
.tab:hover { color: #ddd; }
.tab.active { background: var(--accent); color: #fff; }

.tab-group {
  display: flex;
  gap: 2px;
  border-radius: var(--radius);
  overflow: hidden;
}
.tab-group .tab {
  border-radius: 0;
  background: var(--bg-surface);
}
.tab-group .tab:first-child { border-radius: var(--radius-sm) 0 0 var(--radius-sm); }
.tab-group .tab:last-child { border-radius: 0 var(--radius-sm) var(--radius-sm) 0; }
.tab-group .tab.active { background: var(--accent); }

/* Cards */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px;
}
.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}
.card-title {
  font-size: 15px;
  font-weight: 600;
  color: #fff;
}

/* Price display */
.price { font-family: var(--font-mono); font-weight: 600; }
.price-lg { font-size: 32px; }
.price-md { font-size: 18px; }
.price-sm { font-size: 14px; }
.price-xs { font-size: 13px; }

.change-positive { color: var(--positive); }
.change-negative { color: var(--negative); }
.change-neutral { color: var(--text-secondary); }

.badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 600;
  font-family: var(--font-mono);
}
.badge-positive { background: var(--positive-dim); color: var(--positive); }
.badge-negative { background: var(--negative-dim); color: var(--negative); }

/* Sparkline placeholders */
.sparkline {
  width: 80px;
  height: 32px;
}
.sparkline-up { stroke: var(--positive); }
.sparkline-down { stroke: var(--negative); }

/* Section spacing */
.section { padding: 40px 24px; }
.section-sm { padding: 24px; }
.container { max-width: 1400px; margin: 0 auto; }

/* Grid */
.grid { display: grid; gap: 16px; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }
.grid-6 { grid-template-columns: repeat(6, 1fr); }

/* Market summary bar */
.market-bar {
  display: flex;
  overflow-x: auto;
  gap: 0;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  padding: 0;
}
.market-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  border-right: 1px solid var(--border-color);
  white-space: nowrap;
  cursor: pointer;
  transition: background var(--transition);
  min-width: fit-content;
}
.market-item:hover { background: var(--bg-hover); }
.market-item .ticker { font-size: 11px; color: var(--text-muted); font-weight: 600; }
.market-item .price { font-size: 13px; }
.market-item .change { font-size: 12px; font-weight: 600; }
.market-item .name { font-size: 12px; color: var(--text-secondary); }

/* Hero */
.hero {
  text-align: center;
  padding: 80px 24px 48px;
  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
}
.hero h1 { font-size: 42px; font-weight: 700; max-width: 800px; margin: 0 auto 16px; line-height: 1.2; }
.hero p { font-size: 17px; color: var(--text-secondary); max-width: 650px; margin: 0 auto 32px; }
.hero-actions { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }

/* Footer */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 48px 24px 24px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 32px;
  max-width: 1400px;
  margin: 0 auto;
}
.footer-col h4 { font-size: 13px; font-weight: 600; color: #fff; margin-bottom: 12px; text-transform: uppercase; letter-spacing: 0.5px; }
.footer-col a { display: block; font-size: 13px; color: var(--text-secondary); padding: 3px 0; }
.footer-col a:hover { color: #fff; }
.footer-bottom {
  max-width: 1400px;
  margin: 32px auto 0;
  padding-top: 20px;
  border-top: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12px;
  color: var(--text-muted);
  flex-wrap: wrap;
  gap: 12px;
}

/* Table styles */
.data-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.data-table th {
  text-align: left;
  padding: 8px 12px;
  color: var(--text-secondary);
  font-weight: 500;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-bottom: 1px solid var(--border-color);
}
.data-table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border-color);
  font-family: var(--font-mono);
  font-size: 13px;
}
.data-table tr:hover td { background: var(--bg-hover); }
.data-table .name-cell { font-family: var(--font); color: var(--text-primary); }
.data-table .ticker-cell { color: var(--text-secondary); font-size: 11px; }

/* Watchlist */
.watchlist { max-height: calc(100vh - 200px); overflow-y: auto; }
.watchlist-group { margin-bottom: 2px; }
.watchlist-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  cursor: pointer;
  background: var(--bg-surface);
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--text-secondary);
  user-select: none;
}
.watchlist-header:hover { background: var(--bg-hover); }
.watchlist-header .arrow {
  transition: transform var(--transition);
  font-size: 10px;
}
.watchlist-header.open .arrow { transform: rotate(90deg); }
.watchlist-body { display: none; }
.watchlist-body.open { display: block; }
.watchlist-row {
  display: grid;
  grid-template-columns: 40px 1fr 1fr 1fr;
  gap: 8px;
  padding: 6px 12px;
  font-size: 12px;
  border-bottom: 1px solid rgba(255,255,255,0.04);
  cursor: pointer;
  align-items: center;
}
.watchlist-row:hover { background: var(--bg-hover); }
.watchlist-row .sym { font-weight: 600; color: var(--accent); font-size: 12px; }
.watchlist-row .price { font-family: var(--font-mono); text-align: right; font-size: 12px; }
.watchlist-row .chg { font-family: var(--font-mono); text-align: right; font-size: 11px; }

/* Idea cards */
.idea-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition);
}
.idea-card:hover { border-color: var(--border-light); }
.idea-card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 16px;
  border-bottom: 1px solid var(--border-color);
}
.idea-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--bg-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 14px;
  color: var(--accent);
}
.idea-user { font-size: 13px; font-weight: 600; }
.idea-meta { font-size: 11px; color: var(--text-muted); }
.idea-card-body { padding: 16px; }
.idea-card-body h3 { font-size: 15px; margin-bottom: 8px; }
.idea-card-body p { font-size: 13px; color: var(--text-secondary); line-height: 1.6; }
.idea-tags { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 12px; }
.idea-tag {
  padding: 3px 8px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  background: var(--bg-surface);
  color: var(--text-secondary);
}
.idea-card-footer {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 12px 16px;
  border-top: 1px solid var(--border-color);
  font-size: 12px;
  color: var(--text-muted);
}
.idea-stat { display: flex; align-items: center; gap: 4px; }

/* Chart workspace */
.chart-workspace {
  display: grid;
  grid-template-columns: 260px 1fr 320px;
  height: calc(100vh - 56px);
  gap: 0;
}
.chart-left-panel {
  background: var(--bg-secondary);
  border-right: 1px solid var(--border-color);
  overflow-y: auto;
  padding: 0;
}
.chart-main {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.chart-right-panel {
  background: var(--bg-secondary);
  border-left: 1px solid var(--border-color);
  overflow-y: auto;
  padding: 16px;
}
.chart-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  flex-wrap: wrap;
}
.chart-canvas-area {
  flex: 1;
  position: relative;
  background: var(--bg-primary);
  min-height: 400px;
}
.chart-canvas-area canvas {
  display: block;
  width: 100%;
  height: 100%;
}

/* Stock detail panel */
.detail-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 20px;
}
.detail-ticker { font-size: 28px; font-weight: 700; color: #fff; }
.detail-company { font-size: 14px; color: var(--text-secondary); }
.detail-exchange { font-size: 12px; color: var(--text-muted); }
.detail-price-section { margin-bottom: 20px; }
.detail-metrics {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin: 16px 0;
}
.detail-metric {
  padding: 10px;
  background: var(--bg-surface);
  border-radius: var(--radius);
}
.detail-metric .label { font-size: 11px; color: var(--text-muted); margin-bottom: 4px; }
.detail-metric .value { font-size: 14px; font-weight: 600; font-family: var(--font-mono); }

/* Key stats grid */
.key-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  background: var(--border-color);
  border-radius: var(--radius);
  overflow: hidden;
}
.key-stat {
  padding: 10px 12px;
  background: var(--bg-surface);
}
.key-stat .label { font-size: 11px; color: var(--text-muted); }
.key-stat .value { font-size: 13px; font-weight: 600; margin-top: 2px; }

/* Broker cards */
.broker-card {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 16px;
  padding: 20px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  align-items: center;
}
.broker-logo {
  width: 56px;
  height: 56px;
  border-radius: var(--radius);
  background: var(--bg-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  font-weight: 700;
  color: var(--accent);
}
.broker-info h3 { font-size: 16px; font-weight: 600; margin-bottom: 4px; }
.broker-info .tier {
  display: inline-block;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  font-weight: 600;
}
.tier-platinum { background: rgba(229, 228, 226, 0.15); color: var(--platinum); }
.tier-gold { background: rgba(255, 215, 0, 0.15); color: var(--gold); }

.broker-stats { display: flex; gap: 20px; align-items: center; }
.broker-stat { text-align: center; }
.broker-stat .big { font-size: 18px; font-weight: 700; }
.broker-stat .sub { font-size: 11px; color: var(--text-muted); }
.broker-promo {
  padding: 6px 12px;
  background: var(--accent-dim);
  border-radius: var(--radius);
  font-size: 12px;
  color: var(--accent);
  font-weight: 500;
  text-align: center;
}

/* Stats banner */
.stats-banner {
  display: flex;
  justify-content: center;
  gap: 48px;
  padding: 32px 24px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  margin: 24px 0;
}
.stat-block { text-align: center; }
.stat-block .stat-number { font-size: 36px; font-weight: 700; color: var(--accent); }
.stat-block .stat-label { font-size: 14px; color: var(--text-secondary); margin-top: 4px; }

/* Top stories */
.story-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px;
  transition: border-color var(--transition);
}
.story-card:hover { border-color: var(--border-light); }
.story-source { font-size: 11px; color: var(--accent); font-weight: 600; margin-bottom: 8px; text-transform: uppercase; }
.story-card h3 { font-size: 15px; margin-bottom: 8px; line-height: 1.4; }
.story-card p { font-size: 13px; color: var(--text-secondary); line-height: 1.5; }
.story-time { font-size: 11px; color: var(--text-muted); margin-top: 12px; }

/* Markets page */
.markets-tab-nav {
  position: sticky;
  top: 56px;
  z-index: 50;
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-color);
  padding: 12px 24px;
  display: flex;
  gap: 8px;
  overflow-x: auto;
}
.markets-section { padding: 24px; }
.markets-section-title {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 20px;
  color: #fff;
}
.chart-toggles {
  display: flex;
  gap: 4px;
  align-items: center;
}
.chart-toggle {
  padding: 3px 10px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  color: var(--text-secondary);
  cursor: pointer;
  border: none;
  background: transparent;
  font-family: var(--font);
  transition: all var(--transition);
}
.chart-toggle:hover { color: #ddd; background: var(--bg-hover); }
.chart-toggle.active { background: var(--accent); color: #fff; }

/* Gainers/Losers */
.gainer-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 0;
  border-bottom: 1px solid rgba(255,255,255,0.04);
}

/* Ticker bar mini */
.mini-ticker {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-family: var(--font-mono);
}

/* News headline */
.news-headline {
  padding: 10px 16px;
  background: var(--bg-surface);
  border-radius: var(--radius);
  font-size: 13px;
  color: var(--text-secondary);
  margin-top: 12px;
}

/* Earnings calendar */
.earnings-beat { color: var(--positive); }
.earnings-miss { color: var(--negative); }

/* Pagination */
.pagination {
  display: flex;
  justify-content: center;
  gap: 4px;
  padding: 24px 0;
}
.page-btn {
  width: 36px;
  height: 36px;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border-color);
  background: var(--bg-card);
  color: var(--text-secondary);
  cursor: pointer;
  font-size: 13px;
  font-family: var(--font);
}
.page-btn:hover { background: var(--bg-hover); color: #fff; }
.page-btn.active { background: var(--accent); border-color: var(--accent); color: #fff; }

/* Toggle switch */
.toggle-row {
  display: flex;
  align-items: center;
  gap: 8px;
}
.toggle {
  position: relative;
  width: 40px;
  height: 22px;
  border-radius: 11px;
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  cursor: pointer;
  transition: all var(--transition);
}
.toggle.on { background: var(--accent); border-color: var(--accent); }
.toggle::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  transition: transform var(--transition);
}
.toggle.on::after { transform: translateX(18px); }

/* Empty state */
.empty-state {
  text-align: center;
  padding: 48px 24px;
  color: var(--text-muted);
}

/* Scrollbar */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--border-light); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: #555; }

/* Responsive */
@media (max-width: 1200px) {
  .chart-workspace { grid-template-columns: 220px 1fr 280px; }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-6 { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 900px) {
  .chart-workspace { grid-template-columns: 1fr; }
  .chart-left-panel, .chart-right-panel { display: none; }
  .chart-left-panel.mobile-open, .chart-right-panel.mobile-open { display: block; position: fixed; top: 56px; bottom: 0; width: 280px; z-index: 90; overflow-y: auto; }
  .chart-left-panel.mobile-open { left: 0; }
  .chart-right-panel.mobile-open { right: 0; }
  .hero h1 { font-size: 28px; }
  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .grid-6 { grid-template-columns: repeat(2, 1fr); }
  .broker-card { grid-template-columns: 1fr; text-align: center; }
  .broker-stats { justify-content: center; }
  .nav-links { display: none; }
  .nav-links.mobile-open { display: flex; flex-direction: column; position: absolute; top: 56px; left: 0; right: 0; background: var(--bg-secondary); border-bottom: 1px solid var(--border-color); padding: 8px; }
  .mobile-menu-btn { display: flex !important; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 600px) {
  .grid-4, .grid-6 { grid-template-columns: 1fr 1fr; }
  .stats-banner { flex-direction: column; gap: 24px; }
  .hero h1 { font-size: 24px; }
  .section { padding: 24px 16px; }
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  font-size: 24px;
  cursor: pointer;
  padding: 4px;
}

/* Separators */
.divider { border: none; border-top: 1px solid var(--border-color); margin: 16px 0; }

/* Filter bar */
.filter-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

/* Section header */
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}
.section-header h2 { font-size: 22px; font-weight: 700; }

/* Gainers list columns */
.gainers-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

/* Bond yield row */
.yield-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px solid rgba(255,255,255,0.04);
}
.yield-maturity { font-size: 12px; color: var(--text-muted); width: 60px; }
.yield-value { font-family: var(--font-mono); font-size: 14px; font-weight: 600; }
.yield-bar {
  flex: 1;
  height: 4px;
  background: var(--bg-surface);
  border-radius: 2px;
  overflow: hidden;
}
.yield-bar-fill { height: 100%; background: var(--accent); border-radius: 2px; }

/* Icon indicators */
.icon-up { color: var(--positive); }
.icon-down { color: var(--negative); }

/* Chart container */
.chart-container {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

/* ChartPulse — Design System */
:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #1a1a2e;
  --bg-card: #16213e;
  --bg-surface: #1e1e32;
  --bg-hover: #252542;
  --border-color: #2a2a3e;
  --border-light: #353550;
  --text-primary: #f0f0f0;
  --text-secondary: #999;
  --text-muted: #666;
  --accent: #2962FF;
  --accent-hover: #1e4fdb;
  --accent-dim: rgba(41, 98, 255, 0.15);
  --positive: #00C853;
  --positive-dim: rgba(0, 200, 83, 0.12);
  --negative: #F7525F;
  --negative-dim: rgba(247, 82, 95, 0.12);
  --warning: #FFA726;
  --gold: #FFD700;
  --platinum: #E5E4E2;
  --radius: 6px;
  --radius-lg: 10px;
  --radius-sm: 4px;
  --font: 'Inter', 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', monospace;
  --shadow: 0 2px 8px rgba(0,0,0,0.3);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.5);
  --transition: 150ms ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }
body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

a { color: var(--accent); text-decoration: none; }
a:hover { color: #5c85ff; }
ul { list-style: none; }

/* Header / Nav */
.navbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  height: 56px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 100;
  gap: 16px;
}
.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 20px;
  font-weight: 700;
  color: #fff;
  white-space: nowrap;
}
.nav-logo .icon { font-size: 24px; }
.nav-links {
  display: flex;
  gap: 4px;
}
.nav-links a {
  padding: 8px 16px;
  border-radius: var(--radius);
  color: var(--text-secondary);
  font-size: 14px;
  font-weight: 500;
  transition: all var(--transition);
}
.nav-links a:hover, .nav-links a.active { color: #fff; background: var(--bg-hover); }
.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}
.nav-actions .btn { font-size: 13px; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 20px;
  border-radius: var(--radius);
  font-weight: 600;
  font-size: 14px;
  cursor: pointer;
  border: none;
  transition: all var(--transition);
  font-family: var(--font);
  white-space: nowrap;
}
.btn-primary { background: var(--accent); color: #fff; }
.btn-primary:hover { background: var(--accent-hover); }
.btn-outline {
  background: transparent;
  border: 1px solid var(--border-light);
  color: var(--text-primary);
}
.btn-outline:hover { background: var(--bg-hover); border-color: #555; }
.btn-sm { padding: 6px 12px; font-size: 12px; }
.btn-xs { padding: 3px 8px; font-size: 11px; border-radius: var(--radius-sm); }

/* Tabs */
.tabs {
  display: flex;
  gap: 2px;
  background: var(--bg-surface);
  border-radius: var(--radius);
  padding: 3px;
}
.tab {
  padding: 7px 14px;
  border-radius: var(--radius-sm);
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  border: none;
  background: transparent;
  font-family: var(--font);
  transition: all var(--transition);
  white-space: nowrap;
}
.tab:hover { color: #ddd; }
.tab.active { background: var(--accent); color: #fff; }

.tab-group {
  display: flex;
  gap: 2px;
  border-radius: var(--radius);
  overflow: hidden;
}
.tab-group .tab {
  border-radius: 0;
  background: var(--bg-surface);
}
.tab-group .tab:first-child { border-radius: var(--radius-sm) 0 0 var(--radius-sm); }
.tab-group .tab:last-child { border-radius: 0 var(--radius-sm) var(--radius-sm) 0; }
.tab-group .tab.active { background: var(--accent); }

/* Cards */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px;
}
.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}
.card-title {
  font-size: 15px;
  font-weight: 600;
  color: #fff;
}

/* Price display */
.price { font-family: var(--font-mono); font-weight: 600; }
.price-lg { font-size: 32px; }
.price-md { font-size: 18px; }
.price-sm { font-size: 14px; }
.price-xs { font-size: 13px; }

.change-positive { color: var(--positive); }
.change-negative { color: var(--negative); }
.change-neutral { color: var(--text-secondary); }

.badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 600;
  font-family: var(--font-mono);
}
.badge-positive { background: var(--positive-dim); color: var(--positive); }
.badge-negative { background: var(--negative-dim); color: var(--negative); }

/* Sparkline placeholders */
.sparkline {
  width: 80px;
  height: 32px;
}
.sparkline-up { stroke: var(--positive); }
.sparkline-down { stroke: var(--negative); }

/* Section spacing */
.section { padding: 40px 24px; }
.section-sm { padding: 24px; }
.container { max-width: 1400px; margin: 0 auto; }

/* Grid */
.grid { display: grid; gap: 16px; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }
.grid-6 { grid-template-columns: repeat(6, 1fr); }

/* Market summary bar */
.market-bar {
  display: flex;
  overflow-x: auto;
  gap: 0;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  padding: 0;
}
.market-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  border-right: 1px solid var(--border-color);
  white-space: nowrap;
  cursor: pointer;
  transition: background var(--transition);
  min-width: fit-content;
}
.market-item:hover { background: var(--bg-hover); }
.market-item .ticker { font-size: 11px; color: var(--text-muted); font-weight: 600; }
.market-item .price { font-size: 13px; }
.market-item .change { font-size: 12px; font-weight: 600; }
.market-item .name { font-size: 12px; color: var(--text-secondary); }

/* Hero */
.hero {
  text-align: center;
  padding: 80px 24px 48px;
  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
}
.hero h1 { font-size: 42px; font-weight: 700; max-width: 800px; margin: 0 auto 16px; line-height: 1.2; }
.hero p { font-size: 17px; color: var(--text-secondary); max-width: 650px; margin: 0 auto 32px; }
.hero-actions { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }

/* Footer */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 48px 24px 24px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 32px;
  max-width: 1400px;
  margin: 0 auto;
}
.footer-col h4 { font-size: 13px; font-weight: 600; color: #fff; margin-bottom: 12px; text-transform: uppercase; letter-spacing: 0.5px; }
.footer-col a { display: block; font-size: 13px; color: var(--text-secondary); padding: 3px 0; }
.footer-col a:hover { color: #fff; }
.footer-bottom {
  max-width: 1400px;
  margin: 32px auto 0;
  padding-top: 20px;
  border-top: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12px;
  color: var(--text-muted);
  flex-wrap: wrap;
  gap: 12px;
}

/* Table styles */
.data-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.data-table th {
  text-align: left;
  padding: 8px 12px;
  color: var(--text-secondary);
  font-weight: 500;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-bottom: 1px solid var(--border-color);
}
.data-table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border-color);
  font-family: var(--font-mono);
  font-size: 13px;
}
.data-table tr:hover td { background: var(--bg-hover); }
.data-table .name-cell { font-family: var(--font); color: var(--text-primary); }
.data-table .ticker-cell { color: var(--text-secondary); font-size: 11px; }

/* Watchlist */
.watchlist { max-height: calc(100vh - 200px); overflow-y: auto; }
.watchlist-group { margin-bottom: 2px; }
.watchlist-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  cursor: pointer;
  background: var(--bg-surface);
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--text-secondary);
  user-select: none;
}
.watchlist-header:hover { background: var(--bg-hover); }
.watchlist-header .arrow {
  transition: transform var(--transition);
  font-size: 10px;
}
.watchlist-header.open .arrow { transform: rotate(90deg); }
.watchlist-body { display: none; }
.watchlist-body.open { display: block; }
.watchlist-row {
  display: grid;
  grid-template-columns: 40px 1fr 1fr 1fr;
  gap: 8px;
  padding: 6px 12px;
  font-size: 12px;
  border-bottom: 1px solid rgba(255,255,255,0.04);
  cursor: pointer;
  align-items: center;
}
.watchlist-row:hover { background: var(--bg-hover); }
.watchlist-row .sym { font-weight: 600; color: var(--accent); font-size: 12px; }
.watchlist-row .price { font-family: var(--font-mono); text-align: right; font-size: 12px; }
.watchlist-row .chg { font-family: var(--font-mono); text-align: right; font-size: 11px; }

/* Idea cards */
.idea-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition);
}
.idea-card:hover { border-color: var(--border-light); }
.idea-card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 16px;
  border-bottom: 1px solid var(--border-color);
}
.idea-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--bg-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 14px;
  color: var(--accent);
}
.idea-user { font-size: 13px; font-weight: 600; }
.idea-meta { font-size: 11px; color: var(--text-muted); }
.idea-card-body { padding: 16px; }
.idea-card-body h3 { font-size: 15px; margin-bottom: 8px; }
.idea-card-body p { font-size: 13px; color: var(--text-secondary); line-height: 1.6; }
.idea-tags { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 12px; }
.idea-tag {
  padding: 3px 8px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  background: var(--bg-surface);
  color: var(--text-secondary);
}
.idea-card-footer {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 12px 16px;
  border-top: 1px solid var(--border-color);
  font-size: 12px;
  color: var(--text-muted);
}
.idea-stat { display: flex; align-items: center; gap: 4px; }

/* Chart workspace */
.chart-workspace {
  display: grid;
  grid-template-columns: 260px 1fr 320px;
  height: calc(100vh - 56px);
  gap: 0;
}
.chart-left-panel {
  background: var(--bg-secondary);
  border-right: 1px solid var(--border-color);
  overflow-y: auto;
  padding: 0;
}
.chart-main {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.chart-right-panel {
  background: var(--bg-secondary);
  border-left: 1px solid var(--border-color);
  overflow-y: auto;
  padding: 16px;
}
.chart-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  flex-wrap: wrap;
}
.chart-canvas-area {
  flex: 1;
  position: relative;
  background: var(--bg-primary);
  min-height: 400px;
}
.chart-canvas-area canvas {
  display: block;
  width: 100%;
  height: 100%;
}

/* Stock detail panel */
.detail-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 20px;
}
.detail-ticker { font-size: 28px; font-weight: 700; color: #fff; }
.detail-company { font-size: 14px; color: var(--text-secondary); }
.detail-exchange { font-size: 12px; color: var(--text-muted); }
.detail-price-section { margin-bottom: 20px; }
.detail-metrics {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin: 16px 0;
}
.detail-metric {
  padding: 10px;
  background: var(--bg-surface);
  border-radius: var(--radius);
}
.detail-metric .label { font-size: 11px; color: var(--text-muted); margin-bottom: 4px; }
.detail-metric .value { font-size: 14px; font-weight: 600; font-family: var(--font-mono); }

/* Key stats grid */
.key-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  background: var(--border-color);
  border-radius: var(--radius);
  overflow: hidden;
}
.key-stat {
  padding: 10px 12px;
  background: var(--bg-surface);
}
.key-stat .label { font-size: 11px; color: var(--text-muted); }
.key-stat .value { font-size: 13px; font-weight: 600; margin-top: 2px; }

/* Broker cards */
.broker-card {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 16px;
  padding: 20px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  align-items: center;
}
.broker-logo {
  width: 56px;
  height: 56px;
  border-radius: var(--radius);
  background: var(--bg-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  font-weight: 700;
  color: var(--accent);
}
.broker-info h3 { font-size: 16px; font-weight: 600; margin-bottom: 4px; }
.broker-info .tier {
  display: inline-block;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  font-weight: 600;
}
.tier-platinum { background: rgba(229, 228, 226, 0.15); color: var(--platinum); }
.tier-gold { background: rgba(255, 215, 0, 0.15); color: var(--gold); }

.broker-stats { display: flex; gap: 20px; align-items: center; }
.broker-stat { text-align: center; }
.broker-stat .big { font-size: 18px; font-weight: 700; }
.broker-stat .sub { font-size: 11px; color: var(--text-muted); }
.broker-promo {
  padding: 6px 12px;
  background: var(--accent-dim);
  border-radius: var(--radius);
  font-size: 12px;
  color: var(--accent);
  font-weight: 500;
  text-align: center;
}

/* Stats banner */
.stats-banner {
  display: flex;
  justify-content: center;
  gap: 48px;
  padding: 32px 24px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  margin: 24px 0;
}
.stat-block { text-align: center; }
.stat-block .stat-number { font-size: 36px; font-weight: 700; color: var(--accent); }
.stat-block .stat-label { font-size: 14px; color: var(--text-secondary); margin-top: 4px; }

/* Top stories */
.story-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px;
  transition: border-color var(--transition);
}
.story-card:hover { border-color: var(--border-light); }
.story-source { font-size: 11px; color: var(--accent); font-weight: 600; margin-bottom: 8px; text-transform: uppercase; }
.story-card h3 { font-size: 15px; margin-bottom: 8px; line-height: 1.4; }
.story-card p { font-size: 13px; color: var(--text-secondary); line-height: 1.5; }
.story-time { font-size: 11px; color: var(--text-muted); margin-top: 12px; }

/* Markets page */
.markets-tab-nav {
  position: sticky;
  top: 56px;
  z-index: 50;
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-color);
  padding: 12px 24px;
  display: flex;
  gap: 8px;
  overflow-x: auto;
}
.markets-section { padding: 24px; }
.markets-section-title {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 20px;
  color: #fff;
}
.chart-toggles {
  display: flex;
  gap: 4px;
  align-items: center;
}
.chart-toggle {
  padding: 3px 10px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  color: var(--text-secondary);
  cursor: pointer;
  border: none;
  background: transparent;
  font-family: var(--font);
  transition: all var(--transition);
}
.chart-toggle:hover { color: #ddd; background: var(--bg-hover); }
.chart-toggle.active { background: var(--accent); color: #fff; }

/* Gainers/Losers */
.gainer-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 0;
  border-bottom: 1px solid rgba(255,255,255,0.04);
}

/* Ticker bar mini */
.mini-ticker {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-family: var(--font-mono);
}

/* News headline */
.news-headline {
  padding: 10px 16px;
  background: var(--bg-surface);
  border-radius: var(--radius);
  font-size: 13px;
  color: var(--text-secondary);
  margin-top: 12px;
}

/* Earnings calendar */
.earnings-beat { color: var(--positive); }
.earnings-miss { color: var(--negative); }

/* Pagination */
.pagination {
  display: flex;
  justify-content: center;
  gap: 4px;
  padding: 24px 0;
}
.page-btn {
  width: 36px;
  height: 36px;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border-color);
  background: var(--bg-card);
  color: var(--text-secondary);
  cursor: pointer;
  font-size: 13px;
  font-family: var(--font);
}
.page-btn:hover { background: var(--bg-hover); color: #fff; }
.page-btn.active { background: var(--accent); border-color: var(--accent); color: #fff; }

/* Toggle switch */
.toggle-row {
  display: flex;
  align-items: center;
  gap: 8px;
}
.toggle {
  position: relative;
  width: 40px;
  height: 22px;
  border-radius: 11px;
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  cursor: pointer;
  transition: all var(--transition);
}
.toggle.on { background: var(--accent); border-color: var(--accent); }
.toggle::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  transition: transform var(--transition);
}
.toggle.on::after { transform: translateX(18px); }

/* Empty state */
.empty-state {
  text-align: center;
  padding: 48px 24px;
  color: var(--text-muted);
}

/* Scrollbar */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--border-light); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: #555; }

/* Responsive */
@media (max-width: 1200px) {
  .chart-workspace { grid-template-columns: 220px 1fr 280px; }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-6 { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 900px) {
  .chart-workspace { grid-template-columns: 1fr; }
  .chart-left-panel, .chart-right-panel { display: none; }
  .chart-left-panel.mobile-open, .chart-right-panel.mobile-open { display: block; position: fixed; top: 56px; bottom: 0; width: 280px; z-index: 90; overflow-y: auto; }
  .chart-left-panel.mobile-open { left: 0; }
  .chart-right-panel.mobile-open { right: 0; }
  .hero h1 { font-size: 28px; }
  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .grid-6 { grid-template-columns: repeat(2, 1fr); }
  .broker-card { grid-template-columns: 1fr; text-align: center; }
  .broker-stats { justify-content: center; }
  .nav-links { display: none; }
  .nav-links.mobile-open { display: flex; flex-direction: column; position: absolute; top: 56px; left: 0; right: 0; background: var(--bg-secondary); border-bottom: 1px solid var(--border-color); padding: 8px; }
  .mobile-menu-btn { display: flex !important; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 600px) {
  .grid-4, .grid-6 { grid-template-columns: 1fr 1fr; }
  .stats-banner { flex-direction: column; gap: 24px; }
  .hero h1 { font-size: 24px; }
  .section { padding: 24px 16px; }
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  font-size: 24px;
  cursor: pointer;
  padding: 4px;
}

/* Separators */
.divider { border: none; border-top: 1px solid var(--border-color); margin: 16px 0; }

/* Filter bar */
.filter-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

/* Section header */
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}
.section-header h2 { font-size: 22px; font-weight: 700; }

/* Gainers list columns */
.gainers-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

/* Bond yield row */
.yield-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px solid rgba(255,255,255,0.04);
}
.yield-maturity { font-size: 12px; color: var(--text-muted); width: 60px; }
.yield-value { font-family: var(--font-mono); font-size: 14px; font-weight: 600; }
.yield-bar {
  flex: 1;
  height: 4px;
  background: var(--bg-surface);
  border-radius: 2px;
  overflow: hidden;
}
.yield-bar-fill { height: 100%; background: var(--accent); border-radius: 2px; }

/* Icon indicators */
.icon-up { color: var(--positive); }
.icon-down { color: var(--negative); }

/* Chart container */
.chart-container {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

raw_arguments.content:
/* ChartPulse — Design System */
:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #1a1a2e;
  --bg-card: #16213e;
  --bg-surface: #1e1e32;
  --bg-hover: #252542;
  --border-color: #2a2a3e;
  --border-light: #353550;
  --text-primary: #f0f0f0;
  --text-secondary: #999;
  --text-muted: #666;
  --accent: #2962FF;
  --accent-hover: #1e4fdb;
  --accent-dim: rgba(41, 98, 255, 0.15);
  --positive: #00C853;
  --positive-dim: rgba(0, 200, 83, 0.12);
  --negative: #F7525F;
  --negative-dim: rgba(247, 82, 95, 0.12);
  --warning: #FFA726;
  --gold: #FFD700;
  --platinum: #E5E4E2;
  --radius: 6px;
  --radius-lg: 10px;
  --radius-sm: 4px;
  --font: 'Inter', 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', monospace;
  --shadow: 0 2px 8px rgba(0,0,0,0.3);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.5);
  --transition: 150ms ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }
body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

a { color: var(--accent); text-decoration: none; }
a:hover { color: #5c85ff; }
ul { list-style: none; }

/* Header / Nav */
.navbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  height: 56px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 100;
  gap: 16px;
}
.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 20px;
  font-weight: 700;
  color: #fff;
  white-space: nowrap;
}
.nav-logo .icon { font-size: 24px; }
.nav-links {
  display: flex;
  gap: 4px;
}
.nav-links a {
  padding: 8px 16px;
  border-radius: var(--radius);
  color: var(--text-secondary);
  font-size: 14px;
  font-weight: 500;
  transition: all var(--transition);
}
.nav-links a:hover, .nav-links a.active { color: #fff; background: var(--bg-hover); }
.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}
.nav-actions .btn { font-size: 13px; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 20px;
  border-radius: var(--radius);
  font-weight: 600;
  font-size: 14px;
  cursor: pointer;
  border: none;
  transition: all var(--transition);
  font-family: var(--font);
  white-space: nowrap;
}
.btn-primary { background: var(--accent); color: #fff; }
.btn-primary:hover { background: var(--accent-hover); }
.btn-outline {
  background: transparent;
  border: 1px solid var(--border-light);
  color: var(--text-primary);
}
.btn-outline:hover { background: var(--bg-hover); border-color: #555; }
.btn-sm { padding: 6px 12px; font-size: 12px; }
.btn-xs { padding: 3px 8px; font-size: 11px; border-radius: var(--radius-sm); }

/* Tabs */
.tabs {
  display: flex;
  gap: 2px;
  background: var(--bg-surface);
  border-radius: var(--radius);
  padding: 3px;
}
.tab {
  padding: 7px 14px;
  border-radius: var(--radius-sm);
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  border: none;
  background: transparent;
  font-family: var(--font);
  transition: all var(--transition);
  white-space: nowrap;
}
.tab:hover { color: #ddd; }
.tab.active { background: var(--accent); color: #fff; }

.tab-group {
  display: flex;
  gap: 2px;
  border-radius: var(--radius);
  overflow: hidden;
}
.tab-group .tab {
  border-radius: 0;
  background: var(--bg-surface);
}
.tab-group .tab:first-child { border-radius: var(--radius-sm) 0 0 var(--radius-sm); }
.tab-group .tab:last-child { border-radius: 0 var(--radius-sm) var(--radius-sm) 0; }
.tab-group .tab.active { background: var(--accent); }

/* Cards */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px;
}
.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}
.card-title {
  font-size: 15px;
  font-weight: 600;
  color: #fff;
}

/* Price display */
.price { font-family: var(--font-mono); font-weight: 600; }
.price-lg { font-size: 32px; }
.price-md { font-size: 18px; }
.price-sm { font-size: 14px; }
.price-xs { font-size: 13px; }

.change-positive { color: var(--positive); }
.change-negative { color: var(--negative); }
.change-neutral { color: var(--text-secondary); }

.badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 600;
  font-family: var(--font-mono);
}
.badge-positive { background: var(--positive-dim); color: var(--positive); }
.badge-negative { background: var(--negative-dim); color: var(--negative); }

/* Sparkline placeholders */
.sparkline {
  width: 80px;
  height: 32px;
}
.sparkline-up { stroke: var(--positive); }
.sparkline-down { stroke: var(--negative); }

/* Section spacing */
.section { padding: 40px 24px; }
.section-sm { padding: 24px; }
.container { max-width: 1400px; margin: 0 auto; }

/* Grid */
.grid { display: grid; gap: 16px; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }
.grid-6 { grid-template-columns: repeat(6, 1fr); }

/* Market summary bar */
.market-bar {
  display: flex;
  overflow-x: auto;
  gap: 0;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  padding: 0;
}
.market-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  border-right: 1px solid var(--border-color);
  white-space: nowrap;
  cursor: pointer;
  transition: background var(--transition);
  min-width: fit-content;
}
.market-item:hover { background: var(--bg-hover); }
.market-item .ticker { font-size: 11px; color: var(--text-muted); font-weight: 600; }
.market-item .price { font-size: 13px; }
.market-item .change { font-size: 12px; font-weight: 600; }
.market-item .name { font-size: 12px; color: var(--text-secondary); }

/* Hero */
.hero {
  text-align: center;
  padding: 80px 24px 48px;
  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
}
.hero h1 { font-size: 42px; font-weight: 700; max-width: 800px; margin: 0 auto 16px; line-height: 1.2; }
.hero p { font-size: 17px; color: var(--text-secondary); max-width: 650px; margin: 0 auto 32px; }
.hero-actions { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }

/* Footer */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 48px 24px 24px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 32px;
  max-width: 1400px;
  margin: 0 auto;
}
.footer-col h4 { font-size: 13px; font-weight: 600; color: #fff; margin-bottom: 12px; text-transform: uppercase; letter-spacing: 0.5px; }
.footer-col a { display: block; font-size: 13px; color: var(--text-secondary); padding: 3px 0; }
.footer-col a:hover { color: #fff; }
.footer-bottom {
  max-width: 1400px;
  margin: 32px auto 0;
  padding-top: 20px;
  border-top: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12px;
  color: var(--text-muted);
  flex-wrap: wrap;
  gap: 12px;
}

/* Table styles */
.data-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.data-table th {
  text-align: left;
  padding: 8px 12px;
  color: var(--text-secondary);
  font-weight: 500;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-bottom: 1px solid var(--border-color);
}
.data-table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border-color);
  font-family: var(--font-mono);
  font-size: 13px;
}
.data-table tr:hover td { background: var(--bg-hover); }
.data-table .name-cell { font-family: var(--font); color: var(--text-primary); }
.data-table .ticker-cell { color: var(--text-secondary); font-size: 11px; }

/* Watchlist */
.watchlist { max-height: calc(100vh - 200px); overflow-y: auto; }
.watchlist-group { margin-bottom: 2px; }
.watchlist-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  cursor: pointer;
  background: var(--bg-surface);
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--text-secondary);
  user-select: none;
}
.watchlist-header:hover { background: var(--bg-hover); }
.watchlist-header .arrow {
  transition: transform var(--transition);
  font-size: 10px;
}
.watchlist-header.open .arrow { transform: rotate(90deg); }
.watchlist-body { display: none; }
.watchlist-body.open { display: block; }
.watchlist-row {
  display: grid;
  grid-template-columns: 40px 1fr 1fr 1fr;
  gap: 8px;
  padding: 6px 12px;
  font-size: 12px;
  border-bottom: 1px solid rgba(255,255,255,0.04);
  cursor: pointer;
  align-items: center;
}
.watchlist-row:hover { background: var(--bg-hover); }
.watchlist-row .sym { font-weight: 600; color: var(--accent); font-size: 12px; }
.watchlist-row .price { font-family: var(--font-mono); text-align: right; font-size: 12px; }
.watchlist-row .chg { font-family: var(--font-mono); text-align: right; font-size: 11px; }

/* Idea cards */
.idea-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition);
}
.idea-card:hover { border-color: var(--border-light); }
.idea-card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 16px;
  border-bottom: 1px solid var(--border-color);
}
.idea-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--bg-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 14px;
  color: var(--accent);
}
.idea-user { font-size: 13px; font-weight: 600; }
.idea-meta { font-size: 11px; color: var(--text-muted); }
.idea-card-body { padding: 16px; }
.idea-card-body h3 { font-size: 15px; margin-bottom: 8px; }
.idea-card-body p { font-size: 13px; color: var(--text-secondary); line-height: 1.6; }
.idea-tags { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 12px; }
.idea-tag {
  padding: 3px 8px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  background: var(--bg-surface);
  color: var(--text-secondary);
}
.idea-card-footer {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 12px 16px;
  border-top: 1px solid var(--border-color);
  font-size: 12px;
  color: var(--text-muted);
}
.idea-stat { display: flex; align-items: center; gap: 4px; }

/* Chart workspace */
.chart-workspace {
  display: grid;
  grid-template-columns: 260px 1fr 320px;
  height: calc(100vh - 56px);
  gap: 0;
}
.chart-left-panel {
  background: var(--bg-secondary);
  border-right: 1px solid var(--border-color);
  overflow-y: auto;
  padding: 0;
}
.chart-main {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.chart-right-panel {
  background: var(--bg-secondary);
  border-left: 1px solid var(--border-color);
  overflow-y: auto;
  padding: 16px;
}
.chart-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  flex-wrap: wrap;
}
.chart-canvas-area {
  flex: 1;
  position: relative;
  background: var(--bg-primary);
  min-height: 400px;
}
.chart-canvas-area canvas {
  display: block;
  width: 100%;
  height: 100%;
}

/* Stock detail panel */
.detail-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 20px;
}
.detail-ticker { font-size: 28px; font-weight: 700; color: #fff; }
.detail-company { font-size: 14px; color: var(--text-secondary); }
.detail-exchange { font-size: 12px; color: var(--text-muted); }
.detail-price-section { margin-bottom: 20px; }
.detail-metrics {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin: 16px 0;
}
.detail-metric {
  padding: 10px;
  background: var(--bg-surface);
  border-radius: var(--radius);
}
.detail-metric .label { font-size: 11px; color: var(--text-muted); margin-bottom: 4px; }
.detail-metric .value { font-size: 14px; font-weight: 600; font-family: var(--font-mono); }

/* Key stats grid */
.key-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  background: var(--border-color);
  border-radius: var(--radius);
  overflow: hidden;
}
.key-stat {
  padding: 10px 12px;
  background: var(--bg-surface);
}
.key-stat .label { font-size: 11px; color: var(--text-muted); }
.key-stat .value { font-size: 13px; font-weight: 600; margin-top: 2px; }

/* Broker cards */
.broker-card {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 16px;
  padding: 20px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  align-items: center;
}
.broker-logo {
  width: 56px;
  height: 56px;
  border-radius: var(--radius);
  background: var(--bg-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  font-weight: 700;
  color: var(--accent);
}
.broker-info h3 { font-size: 16px; font-weight: 600; margin-bottom: 4px; }
.broker-info .tier {
  display: inline-block;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  font-weight: 600;
}
.tier-platinum { background: rgba(229, 228, 226, 0.15); color: var(--platinum); }
.tier-gold { background: rgba(255, 215, 0, 0.15); color: var(--gold); }

.broker-stats { display: flex; gap: 20px; align-items: center; }
.broker-stat { text-align: center; }
.broker-stat .big { font-size: 18px; font-weight: 700; }
.broker-stat .sub { font-size: 11px; color: var(--text-muted); }
.broker-promo {
  padding: 6px 12px;
  background: var(--accent-dim);
  border-radius: var(--radius);
  font-size: 12px;
  color: var(--accent);
  font-weight: 500;
  text-align: center;
}

/* Stats banner */
.stats-banner {
  display: flex;
  justify-content: center;
  gap: 48px;
  padding: 32px 24px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  margin: 24px 0;
}
.stat-block { text-align: center; }
.stat-block .stat-number { font-size: 36px; font-weight: 700; color: var(--accent); }
.stat-block .stat-label { font-size: 14px; color: var(--text-secondary); margin-top: 4px; }

/* Top stories */
.story-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px;
  transition: border-color var(--transition);
}
.story-card:hover { border-color: var(--border-light); }
.story-source { font-size: 11px; color: var(--accent); font-weight: 600; margin-bottom: 8px; text-transform: uppercase; }
.story-card h3 { font-size: 15px; margin-bottom: 8px; line-height: 1.4; }
.story-card p { font-size: 13px; color: var(--text-secondary); line-height: 1.5; }
.story-time { font-size: 11px; color: var(--text-muted); margin-top: 12px; }

/* Markets page */
.markets-tab-nav {
  position: sticky;
  top: 56px;
  z-index: 50;
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-color);
  padding: 12px 24px;
  display: flex;
  gap: 8px;
  overflow-x: auto;
}
.markets-section { padding: 24px; }
.markets-section-title {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 20px;
  color: #fff;
}
.chart-toggles {
  display: flex;
  gap: 4px;
  align-items: center;
}
.chart-toggle {
  padding: 3px 10px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  color: var(--text-secondary);
  cursor: pointer;
  border: none;
  background: transparent;
  font-family: var(--font);
  transition: all var(--transition);
}
.chart-toggle:hover { color: #ddd; background: var(--bg-hover); }
.chart-toggle.active { background: var(--accent); color: #fff; }

/* Gainers/Losers */
.gainer-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 0;
  border-bottom: 1px solid rgba(255,255,255,0.04);
}

/* Ticker bar mini */
.mini-ticker {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-family: var(--font-mono);
}

/* News headline */
.news-headline {
  padding: 10px 16px;
  background: var(--bg-surface);
  border-radius: var(--radius);
  font-size: 13px;
  color: var(--text-secondary);
  margin-top: 12px;
}

/* Earnings calendar */
.earnings-beat { color: var(--positive); }
.earnings-miss { color: var(--negative); }

/* Pagination */
.pagination {
  display: flex;
  justify-content: center;
  gap: 4px;
  padding: 24px 0;
}
.page-btn {
  width: 36px;
  height: 36px;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border-color);
  background: var(--bg-card);
  color: var(--text-secondary);
  cursor: pointer;
  font-size: 13px;
  font-family: var(--font);
}
.page-btn:hover { background: var(--bg-hover); color: #fff; }
.page-btn.active { background: var(--accent); border-color: var(--accent); color: #fff; }

/* Toggle switch */
.toggle-row {
  display: flex;
  align-items: center;
  gap: 8px;
}
.toggle {
  position: relative;
  width: 40px;
  height: 22px;
  border-radius: 11px;
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  cursor: pointer;
  transition: all var(--transition);
}
.toggle.on { background: var(--accent); border-color: var(--accent); }
.toggle::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  transition: transform var(--transition);
}
.toggle.on::after { transform: translateX(18px); }

/* Empty state */
.empty-state {
  text-align: center;
  padding: 48px 24px;
  color: var(--text-muted);
}

/* Scrollbar */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--border-light); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: #555; }

/* Responsive */
@media (max-width: 1200px) {
  .chart-workspace { grid-template-columns: 220px 1fr 280px; }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-6 { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 900px) {
  .chart-workspace { grid-template-columns: 1fr; }
  .chart-left-panel, .chart-right-panel { display: none; }
  .chart-left-panel.mobile-open, .chart-right-panel.mobile-open { display: block; position: fixed; top: 56px; bottom: 0; width: 280px; z-index: 90; overflow-y: auto; }
  .chart-left-panel.mobile-open { left: 0; }
  .chart-right-panel.mobile-open { right: 0; }
  .hero h1 { font-size: 28px; }
  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .grid-6 { grid-template-columns: repeat(2, 1fr); }
  .broker-card { grid-template-columns: 1fr; text-align: center; }
  .broker-stats { justify-content: center; }
  .nav-links { display: none; }
  .nav-links.mobile-open { display: flex; flex-direction: column; position: absolute; top: 56px; left: 0; right: 0; background: var(--bg-secondary); border-bottom: 1px solid var(--border-color); padding: 8px; }
  .mobile-menu-btn { display: flex !important; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 600px) {
  .grid-4, .grid-6 { grid-template-columns: 1fr 1fr; }
  .stats-banner { flex-direction: column; gap: 24px; }
  .hero h1 { font-size: 24px; }
  .section { padding: 24px 16px; }
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  font-size: 24px;
  cursor: pointer;
  padding: 4px;
}

/* Separators */
.divider { border: none; border-top: 1px solid var(--border-color); margin: 16px 0; }

/* Filter bar */
.filter-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

/* Section header */
.section-header {
